using System.Data.Common;
using QuickSql.Providers.OracleBase;

namespace QuickSql.Providers.ShenTong;

/// <summary>神通 Oscar 的驱动槽位（血统的第二颗叶子）：一个字都不覆写，连这一族唯一那道 protected virtual
/// 的 CreateCodeFirst 也没有继承——缝开着而没走过去。裁决判据是"文档明写的分岔才配覆写"：
/// 本行点名过的分岔只有"CREATE SCHEMA 语义特殊、用户即模式"两颗，都在发射面之外（本仓库不发 CREATE SCHEMA，
/// "契约没写模式就什么都不写"恰是用户即模式的正常形）；IDENTITY 那颗分岔没有读数，裁"不覆写"，
/// 产出仍是血统那句 GENERATED BY DEFAULT AS IDENTITY。内建表来路与达梦同处境：assembly 写 Oscar
/// （文档口径的名字）、从未解析成功过、不写 factoryType 走兜底扫描。"已适配"三句在本家一句都立不起来，
/// 真实例到场第一问：这台库认不认 GENERATED BY DEFAULT AS IDENTITY。</summary>
/// <remarks>没有覆写——连 CreateCodeFirst 都不继承：这一族的缝是为 IDENTITY 那颗分岔留的，
/// 而神通行对那颗分岔没有任何读数，不赌。懒建与缓存都在基类，所以本家拿到的 CodeFirst 实例类型
/// 就是血统自己的 OracleCodeFirst，与达梦的 DamengCodeFirst 在"叶子发的 CodeFirst 类型"这一格上分出两种。</remarks>
[QuickSqlProvider(DbKind.ShenTong)]
public sealed class ShenTongProvider(DbProviderFactory driverFactory)
    : OracleProviderBase(DbKind.ShenTong, driverFactory)
{
    /// <summary>内建表里的 key。assembly 那颗 Oscar 是文档口径的名字，从未解析成功过，
    /// 所以内建表不写 factoryType——省略它走兜底扫描，比猜一个全名更容易成。</summary>
    public const string DriverKey = "shentong";
}
